SELECT LAG(1, 35, 1) OVER (ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), SUM(CASE WHEN JSON_TYPE(x2.v136384) = 'ARRAY' THEN JSON_EXTRACT(x2.v136384, '$.x') ELSE x2.v136384 END) OVER (ORDER BY x2.v136384, x2.v136384, x2.v136384 DESC, x2.v136384, x2.v136384) FROM v136383 AS x2 WINDOW x1 AS (ORDER BY MONTH(x2.v136384) RANGE BETWEEN INTERVAL '-2' HOUR PRECEDING AND INTERVAL '2:2' MINUTE_SECOND FOLLOWING)